package com.didar.easyenglish;
import android.app.*;import android.content.*;import android.os.Build;import java.util.Calendar;
public class ReminderReceiver extends android.content.BroadcastReceiver {
 static String CH="easyenglish_daily",P="easyenglish_settings";
 static void channel(Context c){if(Build.VERSION.SDK_INT>=26){NotificationChannel n=new NotificationChannel(CH,"Easy English reminders",NotificationManager.IMPORTANCE_DEFAULT);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(n);}}
 static void schedule(Context c,boolean enabled,int h,int m,String msg){c.getSharedPreferences(P,0).edit().putBoolean("enabled",enabled).putInt("h",h).putInt("m",m).putString("msg",msg).apply();Intent intent=new Intent(c,ReminderReceiver.class);PendingIntent pi=PendingIntent.getBroadcast(c,120,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(a==null)return;a.cancel(pi);if(!enabled)return;Calendar cal=Calendar.getInstance();cal.set(Calendar.HOUR_OF_DAY,h);cal.set(Calendar.MINUTE,m);cal.set(Calendar.SECOND,0);if(cal.getTimeInMillis()<=System.currentTimeMillis())cal.add(Calendar.DAY_OF_YEAR,1);a.setInexactRepeating(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),AlarmManager.INTERVAL_DAY,pi);}
 static void schedule(Context c){android.content.SharedPreferences p=c.getSharedPreferences(P,0);schedule(c,p.getBoolean("enabled",false),p.getInt("h",19),p.getInt("m",0),p.getString("msg","کاتی فێربوونی ئینگلیزییە"));}
 @Override public void onReceive(Context c,Intent in){channel(c);Intent open=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String txt=c.getSharedPreferences(P,0).getString("msg","کاتی فێربوونە");Notification.Builder b=new Notification.Builder(c,CH).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Easy English").setContentText(txt).setContentIntent(pi).setAutoCancel(true);try{((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(122,b.build());}catch(Exception ignore){}}
}
